<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  const stream = renderToNodeStream(</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">​MyPage</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span>
